'use strict';

// RunFlow Assistant API v1. Assistant writes are proposals only; the coach
// applies them through the existing draft-week endpoint after explicit review.
const http = require('http');
const crypto = require('crypto');
const { URL } = require('url');
const { detailedBlocks } = require('./session-comparison-metrics');
const planner = require('./assistant-planner');
const weekEdit = require('./assistant-week-edit');
const analyst = require('./assistant-analyst');
const football = require('./assistant-football');

const SUPABASE_URL = String(process.env.SUPABASE_URL || '').replace(/\/$/, '');
const SUPABASE_ANON_KEY = String(process.env.SUPABASE_ANON_KEY || '');
const SUPABASE_SERVICE_ROLE_KEY = String(process.env.SUPABASE_SERVICE_ROLE_KEY || '');
const APP_ENCRYPTION_KEY = String(process.env.APP_ENCRYPTION_KEY || '');
const IS_PROD = process.env.NODE_ENV === 'production';
const CREDENTIAL = '__runflow_assistant_credential__';
const PROPOSAL = '__runflow_assistant_proposal__';
const AUDIT = '__runflow_assistant_audit__';
const DRAFT = '__runflow_assistant_draft__';
// Draft lifecycle: draft -> ready | needs_review (Verificador) -> approved | rejected (coach) -> sent.
const DRAFT_KINDS = ['session', 'week'];
const DRAFT_LIGHTS = ['verde', 'ambar', 'rojo'];
const DRAFT_PENDING = ['draft', 'ready', 'needs_review'];
const DRAFT_STATUSES = [...DRAFT_PENDING, 'approved', 'rejected', 'sent'];
const DRAFT_LOCKED = ['approved', 'sent'];
const DRAFT_GOAL = ['si', 'parcial', 'no', 'sin_plan'];
const DRAFT_TOOLS = ['create_week_proposal', 'create_feedback_draft', 'create_season_proposal', 'propose_week_changes'];
const ALLOWED_SCOPES = ['read', 'draft', 'apply'];
const APPLY_TOOLS = ['apply_week_changes'];

function sendJson(res, status, data) {
  const body = JSON.stringify(data);
  res.writeHead(status, {'Content-Type':'application/json; charset=utf-8','Content-Length':Buffer.byteLength(body),'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'});
  res.end(body);
}
async function readJson(req) {
  let body=''; for await (const chunk of req) { body+=chunk; if(body.length>1000000) throw Object.assign(new Error('Solicitud demasiado grande.'),{status:413}); }
  try { return body ? JSON.parse(body) : {}; } catch { throw Object.assign(new Error('JSON no válido.'),{status:400}); }
}
function cookies(req){const out={};String(req.headers.cookie||'').split(';').forEach(part=>{const i=part.indexOf('=');if(i>0)out[part.slice(0,i).trim()]=decodeURIComponent(part.slice(i+1).trim())});return out}
function cookie(name,value,maxAge){return `${name}=${encodeURIComponent(value)}; Path=/; HttpOnly; SameSite=Lax${IS_PROD?'; Secure':''}; Max-Age=${maxAge}`}
function safe(value,max=5000){return String(value??'').trim().slice(0,max)}
function validDate(value){return /^\d{4}-\d{2}-\d{2}$/.test(String(value||''))?String(value):null}
function localDate(){return new Intl.DateTimeFormat('en-CA',{timeZone:process.env.RUNFLOW_TIMEZONE||'Europe/Madrid',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function addDays(iso,n){const d=new Date(`${iso}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
function sha(value){return crypto.createHash('sha256').update(String(value)).digest('hex')}
function secret(){if(!APP_ENCRYPTION_KEY&&!SUPABASE_SERVICE_ROLE_KEY)throw Object.assign(new Error('Asistente RunFlow no está configurado.'),{status:503});return APP_ENCRYPTION_KEY||SUPABASE_SERVICE_ROLE_KEY}

async function fetchJson(url,options={}){const response=await fetch(url,options),text=await response.text();let data;try{data=text?JSON.parse(text):null}catch{data=text}if(!response.ok){const message=data&&typeof data==='object'?(data.message||data.error_description||data.error||data.details):data;throw Object.assign(new Error(message||`HTTP ${response.status}`),{status:response.status})}return data}
async function sb(table,query='',options={}){if(!SUPABASE_URL||!SUPABASE_SERVICE_ROLE_KEY)throw Object.assign(new Error('Supabase no está configurado.'),{status:503});const headers={apikey:SUPABASE_SERVICE_ROLE_KEY,Authorization:`Bearer ${SUPABASE_SERVICE_ROLE_KEY}`,...(options.body!==undefined?{'Content-Type':'application/json'}:{}),...(options.prefer?{Prefer:options.prefer}:{})};return fetchJson(`${SUPABASE_URL}/rest/v1/${table}${query?`?${query}`:''}`,{method:options.method||'GET',headers,body:options.body===undefined?undefined:JSON.stringify(options.body)})}
function integrationKey(){if(!APP_ENCRYPTION_KEY||APP_ENCRYPTION_KEY.length<24)throw Object.assign(new Error('Falta APP_ENCRYPTION_KEY o es demasiado corta.'),{status:503});try{const raw=Buffer.from(APP_ENCRYPTION_KEY,'base64');if(raw.length===32&&raw.toString('base64').replace(/=+$/,'')===APP_ENCRYPTION_KEY.replace(/=+$/,''))return raw}catch{}return crypto.createHash('sha256').update(APP_ENCRYPTION_KEY,'utf8').digest()}
function decryptIntegration(record){const decipher=crypto.createDecipheriv('aes-256-gcm',integrationKey(),Buffer.from(record.secret_iv,'base64'));decipher.setAuthTag(Buffer.from(record.secret_tag,'base64'));return Buffer.concat([decipher.update(Buffer.from(record.secret_ciphertext,'base64')),decipher.final()]).toString('utf8')}
async function intervalsKey(athleteId){const rows=await sb('athlete_integrations',`athlete_id=eq.${encodeURIComponent(athleteId)}&provider=eq.intervals&status=eq.connected&select=secret_ciphertext,secret_iv,secret_tag&limit=1`);return rows[0]?decryptIntegration(rows[0]):null}
async function intervalsJson(apiKey,path){return fetchJson(`https://intervals.icu/api/v1${path}`,{headers:{Authorization:`Basic ${Buffer.from(`API_KEY:${apiKey}`).toString('base64')}`,Accept:'application/json'}})}
function intervalsObject(value){if(value&&typeof value==='object'&&!Array.isArray(value)&&value.activity&&typeof value.activity==='object')return value.activity;return value&&typeof value==='object'?value:{}}
function intervalsStreams(value){if(Array.isArray(value))return value;if(value&&Array.isArray(value.streams))return value.streams;if(value&&Array.isArray(value.data))return value.data;return[]}
async function authUser(access){return fetchJson(`${SUPABASE_URL}/auth/v1/user`,{headers:{apikey:SUPABASE_ANON_KEY,Authorization:`Bearer ${access}`}})}
async function authRefresh(refresh){return fetchJson(`${SUPABASE_URL}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:SUPABASE_ANON_KEY,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:refresh})})}
async function coachSession(req,res){const c=cookies(req);let access=c.rf_access,refresh=c.rf_refresh;if(!access)throw Object.assign(new Error('Debes iniciar sesión como entrenador.'),{status:401});let user;try{user=await authUser(access)}catch{if(!refresh)throw Object.assign(new Error('Debes iniciar sesión como entrenador.'),{status:401});const renewed=await authRefresh(refresh);access=renewed.access_token;refresh=renewed.refresh_token||refresh;user=renewed.user||await authUser(access);res.setHeader('Set-Cookie',[cookie('rf_access',access,Math.max(60,Number(renewed.expires_in)||3600)),cookie('rf_refresh',refresh,2592000)])}const roles=(await sb('user_roles',`user_id=eq.${encodeURIComponent(user.id)}&select=role`)).map(x=>x.role);if(!roles.includes('coach'))throw Object.assign(new Error('No tienes permiso de entrenador.'),{status:403});return{user,roles}}
async function coachAthlete(coachId,athleteId){const rows=await sb('coach_athletes',`coach_user_id=eq.${encodeURIComponent(coachId)}&athlete_id=eq.${encodeURIComponent(athleteId)}&select=athlete_id&limit=1`);if(!rows.length)throw Object.assign(new Error('No tienes acceso a este deportista.'),{status:403})}

function signToken(payload){const encoded=Buffer.from(JSON.stringify(payload)).toString('base64url');const signature=crypto.createHmac('sha256',secret()).update(encoded).digest('base64url');return `rfa1.${encoded}.${signature}`}
function decodeToken(token){const parts=String(token||'').split('.');if(parts.length!==3||parts[0]!=='rfa1')return null;const expected=crypto.createHmac('sha256',secret()).update(parts[1]).digest(),received=Buffer.from(parts[2],'base64url');if(received.length!==expected.length||!crypto.timingSafeEqual(received,expected))return null;try{const data=JSON.parse(Buffer.from(parts[1],'base64url').toString('utf8'));if(!data.id||!data.coach_user_id||Number(data.exp)<=Math.floor(Date.now()/1000))return null;return data}catch{return null}}
// ChatGPT connectors cannot send an Authorization header, so /mcp also accepts the credential as ?key=.
async function assistantSession(req,scope='read',queryKey=''){const header=String(req.headers.authorization||'');const raw=header.startsWith('Bearer ')?header.slice(7).trim():String(queryKey||'').trim();const payload=decodeToken(raw);if(!payload)throw Object.assign(new Error('Credencial Asistente RunFlow no válida o caducada.'),{status:401});const rows=await sb('workout_templates',`id=eq.${encodeURIComponent(payload.id)}&coach_user_id=eq.${encodeURIComponent(payload.coach_user_id)}&category=eq.${encodeURIComponent(CREDENTIAL)}&select=id,template_data&limit=1`);const record=rows[0]?.template_data||{};if(!rows.length||record.status!=='active'||record.token_hash!==sha(raw))throw Object.assign(new Error('Credencial Asistente RunFlow revocada.'),{status:401});const scopes=[...(Array.isArray(record.scopes)?record.scopes:[])];if(scopes.includes('draft')&&record.apply_disabled!==true&&!scopes.includes('apply'))scopes.push('apply');if(!scopes.includes(scope))throw Object.assign(new Error(scope==='apply'?'El entrenador ha apagado el modo directo en Ajustes › Conexiones (“Puede aplicar y publicar cambios”). Usa propose_week_changes.':`La credencial no tiene permiso ${scope}.`),{status:403});return{coach_user_id:payload.coach_user_id,credential_id:payload.id,scopes}}
async function internalRow(coachId,category,name,data,athleteId=null){const row={id:crypto.randomUUID(),coach_user_id:coachId,athlete_id:athleteId,name:safe(name,160)||'RunFlow Assistant',category,sport:'Internal',stimulus:'assistant',template_data:data,created_at:new Date().toISOString(),updated_at:new Date().toISOString()};const rows=await sb('workout_templates','',{method:'POST',body:row,prefer:'return=representation'});return rows[0]||row}
async function audit(session,action,detail={}){try{await internalRow(session.coach_user_id,AUDIT,action,{action,credential_id:session.credential_id,detail,recorded_at:new Date().toISOString()})}catch(error){console.error('[assistant-api] audit',error.message)}}

async function createCredential(session,body){const days=Math.max(1,Math.min(90,Number(body.expires_days)||30));const scopes=[...new Set((Array.isArray(body.scopes)?body.scopes:['read','draft']).filter(x=>ALLOWED_SCOPES.includes(x)))];if(!scopes.includes('read'))scopes.unshift('read');const id=crypto.randomUUID(),exp=Math.floor(Date.now()/1000)+days*86400;const token=signToken({id,coach_user_id:session.user.id,scopes,exp});const data={status:'active',scopes,token_hash:sha(token),expires_at:new Date(exp*1000).toISOString(),created_at:new Date().toISOString()};await sb('workout_templates','',{method:'POST',body:{id,coach_user_id:session.user.id,athlete_id:null,name:safe(body.name,160)||'Asistente RunFlow',category:CREDENTIAL,sport:'Internal',stimulus:'assistant_access',template_data:data,created_at:data.created_at,updated_at:data.created_at},prefer:'return=minimal'});return{token,credential:{id,name:safe(body.name,160)||'Asistente RunFlow',scopes,expires_at:data.expires_at,status:'active'}}}
async function listCredentials(coachId){const rows=await sb('workout_templates',`coach_user_id=eq.${encodeURIComponent(coachId)}&category=eq.${encodeURIComponent(CREDENTIAL)}&select=id,name,template_data,created_at&order=created_at.desc`);return rows.map(x=>({id:x.id,name:x.name,created_at:x.created_at,...x.template_data,token_hash:undefined}))}
async function revokeCredential(coachId,id){const rows=await sb('workout_templates',`id=eq.${encodeURIComponent(id)}&coach_user_id=eq.${encodeURIComponent(coachId)}&category=eq.${encodeURIComponent(CREDENTIAL)}&select=template_data&limit=1`);if(!rows.length)throw Object.assign(new Error('Credencial no encontrada.'),{status:404});await sb('workout_templates',`id=eq.${encodeURIComponent(id)}`,{method:'PATCH',body:{template_data:{...rows[0].template_data,status:'revoked',revoked_at:new Date().toISOString()},updated_at:new Date().toISOString()},prefer:'return=minimal'})}
async function athletes(coachId){const links=await sb('coach_athletes',`coach_user_id=eq.${encodeURIComponent(coachId)}&select=athlete_id`);const ids=links.map(x=>x.athlete_id);if(!ids.length)return[];return sb('athletes',`id=in.(${ids.join(',')})&lifecycle_status=eq.active&select=id,display_name,email,intervals_status,lifecycle_status&order=display_name.asc`)}
async function dailyReport(coachId,athleteId,date){await coachAthlete(coachId,athleteId);const day=validDate(date)||localDate();const [athlete,weeks,activities,logs]=await Promise.all([sb('athletes',`id=eq.${encodeURIComponent(athleteId)}&select=id,display_name&limit=1`),sb('training_weeks',`athlete_id=eq.${encodeURIComponent(athleteId)}&week_start=lte.${day}&end_date=gte.${day}&select=id,week_start,title,week_type,coach_comment,target_load,status`),sb('activities',`athlete_id=eq.${encodeURIComponent(athleteId)}&activity_date=gte.${day}&activity_date=lt.${addDays(day,1)}&select=*&order=activity_date.asc`),sb('manual_session_logs',`athlete_id=eq.${encodeURIComponent(athleteId)}&created_at=gte.${day}T00:00:00Z&created_at=lt.${addDays(day,1)}T00:00:00Z&select=*&order=created_at.asc`)]);const week=weeks[0]||null;const workouts=week?await sb('workouts',`training_week_id=eq.${encodeURIComponent(week.id)}&workout_date=eq.${day}&select=*&order=workout_date.asc`):[];let apiKey=null;try{apiKey=activities.length?await intervalsKey(athleteId):null}catch(error){console.error('[assistant-api] intervals key',error.message)}const enrichedActivities=await Promise.all(activities.map(async activity=>{const workout=workouts.find(item=>String(item.id)===String(activity.workout_id))||workouts[0]||null;if(!apiKey||!activity.intervals_activity_id||!workout)return activity;try{const externalId=encodeURIComponent(activity.intervals_activity_id);const [detail,streamResponse]=await Promise.all([intervalsJson(apiKey,`/activity/${externalId}?intervals=true`),intervalsJson(apiKey,`/activity/${externalId}/streams.json`)]);const raw=intervalsObject(detail);const streams=intervalsStreams(streamResponse);return{...activity,block_analysis:detailedBlocks({...activity,raw_summary:raw,streams},workout),analysis_source:{planned_structure:true,intervals_detail:true,streams:streams.map(item=>item&&item.type).filter(Boolean)}}}catch(error){console.error('[assistant-api] detailed activity',error.message);return{...activity,block_analysis_error:'No se pudo recuperar el detalle temporal de Intervals.'}}}));return{date:day,athlete:athlete[0]||{id:athleteId},planned:{week,workouts},performed:{activities:enrichedActivities,feedback:logs},summary:{planned_sessions:workouts.length,recorded_activities:activities.length,feedback_entries:logs.filter(x=>x.workout_id).length,needs_review:workouts.length!==activities.length||logs.some(x=>Number(x.pain)>0)}}}
function cleanWorkout(item,index,weekStart){const date=validDate(item.workout_date)||addDays(weekStart,Math.min(index,6));return{...(item.id?{id:safe(item.id,80)}:{}),workout_date:date,sport:safe(item.sport||'Run',40),title:safe(item.title||'Sesión',160),summary:safe(item.summary,3000),structured_description:safe(item.structured_description||item.summary,10000),planned_load:Math.max(0,Math.min(1000,Number(item.planned_load)||0)),priority:['A','B','C'].includes(item.priority)?item.priority:'B',planned_duration_min:item.planned_duration_min==null?null:Math.max(0,Math.min(2000,Number(item.planned_duration_min)||0)),planned_distance_km:item.planned_distance_km==null?null:Math.max(0,Number(item.planned_distance_km)||0),planned_elevation_m:item.planned_elevation_m==null?null:Math.max(0,Number(item.planned_elevation_m)||0),blocks:Array.isArray(item.blocks)?item.blocks.slice(0,30):[],...(item.optional?{optional:true}:{})}}
async function createProposal(session,athleteId,body){await coachAthlete(session.coach_user_id,athleteId);const weekStart=validDate(body.week_start);if(!weekStart)throw Object.assign(new Error('La propuesta necesita week_start.'),{status:400});const workouts=Array.isArray(body.workouts)?body.workouts.slice(0,30).map((x,i)=>cleanWorkout(x,i,weekStart)):[];const verification=await planner.verifyWeekProposal(sb,athleteId,weekStart,workouts,body.semaforo);if(!verification.ok){await audit(session,'proposal_blocked',{athlete_id:athleteId,week_start:weekStart,failures:verification.failures.map(x=>x.rule)});return{rejected:true,verification}}const objetivoAtleta=safe(body.objetivo_atleta,400).replace(/\s+/g,' '),objetivoCoach=safe(body.objetivo_coach,12000);if(!objetivoAtleta||objetivoAtleta.length>140)return{rejected:true,errors:[objetivoAtleta?`objetivo_atleta tiene ${objetivoAtleta.length} caracteres: tiene que ser una sola frase de 140 como mucho.`:'Falta objetivo_atleta: una frase corta para el atleta con lo que buscamos esta semana.']};if(!objetivoCoach)return{rejected:true,errors:['Falta objetivo_coach: explica a fondo al entrenador qué buscamos esta semana.']};const data={kind:'week',verification,semaforo:safe(body.semaforo,10)||null,status:'proposed',week_start:weekStart,title:safe(body.title||'Propuesta Asistente RunFlow',250),reason:safe(body.reason,4000),objetivo_atleta:objetivoAtleta,objetivo_coach:objetivoCoach,week:{week_start:weekStart,week_type:safe(body.week_type||'Propuesta asistida',80),title:safe(body.title,250),coach_comment:objetivoAtleta,target_load:Number.isFinite(Number(body.target_load))?Number(body.target_load):workouts.reduce((s,x)=>s+Number(x.planned_load||0),0),status:'draft',workouts},created_at:new Date().toISOString(),origin:'assistant'};const row=await internalRow(session.coach_user_id,PROPOSAL,data.title,data,athleteId);await audit(session,'proposal_created',{proposal_id:row.id,athlete_id:athleteId,week_start:weekStart});return{id:row.id,athlete_id:athleteId,...data}}
// Agente Planificador: temporada completa. Si el Verificador encuentra fallos no se guarda nada y el agente recibe los fallos para corregirlos.
async function createSeasonProposal(session,athleteId,body){await coachAthlete(session.coach_user_id,athleteId);const result=await planner.seasonProposal(sb,athleteId,body,localDate());if(!result.ok){await audit(session,'season_proposal_blocked',{athlete_id:athleteId,failures:result.verification.failures.map(x=>x.rule)});return{rejected:true,verification:result.verification,preview:result.preview}}
  const existing=(await proposals(session.coach_user_id,'proposed')).filter(x=>x.kind==='season'&&x.athlete_id===athleteId);
  for(const old of existing){await sb('workout_templates',`id=eq.${encodeURIComponent(old.id)}`,{method:'PATCH',body:{template_data:{...stripView(old),status:'replaced',reviewed_at:new Date().toISOString()},updated_at:new Date().toISOString()},prefer:'return=minimal'})}
  const row=await internalRow(session.coach_user_id,PROPOSAL,result.data.title,result.data,athleteId);await audit(session,'season_proposal_created',{proposal_id:row.id,athlete_id:athleteId,start:result.data.start,end:result.data.end,replaced:existing.length});
  return{proposal:{id:row.id,athlete_id:athleteId,...result.data},preview:result.preview,replaced:existing.map(x=>x.id),next:'El entrenador la verá en Planificación › Propuesta del Planificador. Nada se crea hasta que la apruebe.'}}
// Agente Planificador: cambios en una semana que ya está en el calendario. Solo propuesta;
// el Verificador bloquea fallos nuevos y el entrenador la aprueba en Propuestas pendientes.
async function createWeekEdit(session,athleteId,body){await coachAthlete(session.coach_user_id,athleteId);const today=localDate();const result=await weekEdit.buildWeekEdit(sb,athleteId,body,today,workouts=>planner.verifyWeekProposal(sb,athleteId,validDate(body.week_start),workouts,body.semaforo));if(result.rejected){await audit(session,'week_edit_blocked',{athlete_id:athleteId,week_start:body.week_start,errors:result.errors||[],failures:(result.verification?.failures||[]).map(x=>x.rule)});return result}
  const existing=(await proposals(session.coach_user_id,'proposed')).filter(x=>x.kind==='week_edit'&&x.athlete_id===athleteId&&x.week_start===result.data.week_start);
  for(const old of existing){await sb('workout_templates',`id=eq.${encodeURIComponent(old.id)}`,{method:'PATCH',body:{template_data:{...stripView(old),status:'replaced',reviewed_at:new Date().toISOString()},updated_at:new Date().toISOString()},prefer:'return=minimal'})}
  const row=await internalRow(session.coach_user_id,PROPOSAL,result.data.title,result.data,athleteId);await audit(session,'week_edit_created',{proposal_id:row.id,athlete_id:athleteId,week_start:result.data.week_start,changes:result.data.changes.length,replaced:existing.length});
  return{proposal:{id:row.id,athlete_id:athleteId,...result.data},replaced:existing.map(x=>x.id),next:result.data.base.published?'El entrenador la verá en Ajustes › Conexiones › Propuestas pendientes. La semana está publicada: al aprobarla, el cambio llega al atleta (y a Intervals). Hasta entonces no cambia nada.':'El entrenador la verá en Ajustes › Conexiones › Propuestas pendientes. Al aprobarla se guarda en el calendario como borrador. Hasta entonces no cambia nada.'}}
// Modo directo: solo con el permiso "apply" que el entrenador activa en Conexiones.
// Mismo Verificador y mismas protecciones; se aplica en el momento y queda en el historial.
async function applyWeekEdit(session,athleteId,body){await coachAthlete(session.coach_user_id,athleteId);const confirmation=safe(body.coach_confirmation,1000)||'Decidido con el entrenador en el chat';const writer=globalThis.__runflowWeekWriter;if(!writer)throw Object.assign(new Error('RunFlow no puede aplicar cambios ahora mismo.'),{status:503});
  const result=await weekEdit.buildWeekEdit(sb,athleteId,body,localDate(),workouts=>planner.verifyWeekProposal(sb,athleteId,validDate(body.week_start),workouts,body.semaforo));if(result.rejected){await audit(session,'week_apply_blocked',{athlete_id:athleteId,week_start:body.week_start,errors:result.errors||[],failures:(result.verification?.failures||[]).map(x=>x.rule)});return result}
  const publish=result.data.base.published||body.publish===true;const saved=publish?await writer.publish(athleteId,result.data.week):{week:await writer.saveDraft(athleteId,result.data.week)};
  const pending=(await proposals(session.coach_user_id,'proposed')).filter(x=>x.kind==='week_edit'&&x.athlete_id===athleteId&&x.week_start===result.data.week_start);
  for(const old of pending){await sb('workout_templates',`id=eq.${encodeURIComponent(old.id)}`,{method:'PATCH',body:{template_data:{...stripView(old),status:'replaced',reviewed_at:new Date().toISOString()},updated_at:new Date().toISOString()},prefer:'return=minimal'})}
  const data={...result.data,status:'applied',applied_at:new Date().toISOString(),published:publish,coach_confirmation:confirmation};const row=await internalRow(session.coach_user_id,PROPOSAL,data.title,data,athleteId);
  await audit(session,'week_edit_applied',{proposal_id:row.id,athlete_id:athleteId,week_start:data.week_start,published:publish,changes:data.changes.length});
  return{applied:true,id:row.id,week_start:data.week_start,published:publish,changes:data.changes,verification:data.verification,intervals:saved.intervals||null,sessions:(saved.week?.workouts||[]).map(w=>({workout_id:w.id,workout_date:w.workout_date,title:w.title,planned_duration_min:w.planned_duration_min})),next:publish?'Aplicado y publicado: el atleta ya lo ve en la app y en Intervals.':'Aplicado en el calendario como borrador: el atleta no lo ve hasta que se publique.'}}
async function setApply(coachId,id,on){const rows=await sb('workout_templates',`id=eq.${encodeURIComponent(id)}&coach_user_id=eq.${encodeURIComponent(coachId)}&category=eq.${encodeURIComponent(CREDENTIAL)}&select=template_data&limit=1`);if(!rows.length)throw Object.assign(new Error('Credencial no encontrada.'),{status:404});const record=rows[0].template_data||{};await sb('workout_templates',`id=eq.${encodeURIComponent(id)}`,{method:'PATCH',body:{template_data:{...record,apply_disabled:!on},updated_at:new Date().toISOString()},prefer:'return=minimal'});return{id,apply:on}}
function stripView(x){const{id,athlete_id,name,created_at,...rest}=x;return{...rest,created_at:rest.created_at||created_at}}
async function proposals(coachId,status){const rows=await sb('workout_templates',`coach_user_id=eq.${encodeURIComponent(coachId)}&category=eq.${encodeURIComponent(PROPOSAL)}&select=id,athlete_id,name,template_data,created_at&order=created_at.desc`);return rows.map(x=>({id:x.id,athlete_id:x.athlete_id,name:x.name,created_at:x.created_at,...x.template_data})).filter(x=>!status||x.status===status)}
async function proposalStatus(coachId,id,status,extra={}){if(!['approved','rejected'].includes(status))throw Object.assign(new Error('Estado no válido.'),{status:400});const rows=await sb('workout_templates',`id=eq.${encodeURIComponent(id)}&coach_user_id=eq.${encodeURIComponent(coachId)}&category=eq.${encodeURIComponent(PROPOSAL)}&select=template_data&limit=1`);if(!rows.length)throw Object.assign(new Error('Propuesta no encontrada.'),{status:404});const data={...rows[0].template_data,status,reviewed_at:new Date().toISOString(),...(extra.season_id?{season_id:safe(extra.season_id,80)}:{})};await sb('workout_templates',`id=eq.${encodeURIComponent(id)}`,{method:'PATCH',body:{template_data:data,updated_at:new Date().toISOString()},prefer:'return=minimal'});return{id,...data}}


// Feedback drafts (Analista). The assistant can only write drafts; nothing
// reaches the athlete until the coach approves it in the review tray.
function badRequest(message){return Object.assign(new Error(message),{status:400})}
function textList(value,maxItems=20,maxLength=500){return(Array.isArray(value)?value:[]).map(x=>safe(x,maxLength)).filter(Boolean).slice(0,maxItems)}
function draftKey(kind,athleteId,ref){return `${kind}:${athleteId}:${ref}`}
function cleanDraft(athleteId,body={}){
  const kind=safe(body.kind,20);
  if(!DRAFT_KINDS.includes(kind))throw badRequest('kind debe ser "session" o "week".');
  if(!safe(athleteId,80))throw badRequest('Falta athlete_id.');
  const semaforo=safe(body.semaforo,10).toLowerCase();
  if(!DRAFT_LIGHTS.includes(semaforo))throw badRequest('semaforo debe ser verde, ambar o rojo.');
  const mensaje=safe(body.mensaje_atleta,2000);
  if(!mensaje)throw badRequest('Falta mensaje_atleta.');
  const objetivo=safe(body.objetivo_cumplido,20).toLowerCase();
  if(objetivo&&!DRAFT_GOAL.includes(objetivo))throw badRequest(`objetivo_cumplido debe ser ${DRAFT_GOAL.join(', ')}.`);
  const base={kind,athlete_id:safe(athleteId,80),semaforo,hechos:textList(body.hechos),alertas:textList(body.alertas),mensaje_atleta:mensaje,notas_para_coach:safe(body.notas_para_coach,4000),...(objetivo?{objetivo_cumplido:objetivo}:{}),...(safe(body.efecto_principal,200)?{efecto_principal:safe(body.efecto_principal,200)}:{}),...(safe(body.resumen,600)?{resumen:safe(body.resumen,600)}:{}),...(safe(body.informe_coach,30000)?{informe_coach:safe(body.informe_coach,30000)}:{})};
  if(kind==='session'){
    const activityId=safe(body.activity_id,80),date=validDate(body.date);
    if(!activityId)throw badRequest('Un borrador de sesión necesita activity_id.');
    if(!date)throw badRequest('Un borrador de sesión necesita date (YYYY-MM-DD).');
    return{...base,activity_id:activityId,date,workout_id:safe(body.workout_id,80)||null,idempotency_key:draftKey(kind,base.athlete_id,activityId)};
  }
  const weekStart=validDate(body.week_start);
  if(!weekStart)throw badRequest('Un borrador semanal necesita week_start (YYYY-MM-DD).');
  return{...base,week_start:weekStart,idempotency_key:draftKey(kind,base.athlete_id,weekStart)};
}
function draftView(row){return{id:row.id,athlete_id:row.athlete_id,created_at:row.created_at,updated_at:row.updated_at,...row.template_data}}
// Same session/week => same record. A retry replaces the pending draft
// (keeping the previous message in history) instead of creating a duplicate.
async function saveDraft(coachId,athleteId,body,db=sb){
  const clean=cleanDraft(athleteId,body),now=new Date().toISOString();
  const existing=await db('workout_templates',`coach_user_id=eq.${encodeURIComponent(coachId)}&category=eq.${encodeURIComponent(DRAFT)}&template_data->>idempotency_key=eq.${encodeURIComponent(clean.idempotency_key)}&select=id,athlete_id,template_data,created_at,updated_at&order=created_at.desc&limit=1`);
  const previous=existing[0];
  if(previous){
    const old=previous.template_data||{};
    if(DRAFT_LOCKED.includes(old.status))throw Object.assign(new Error('Este borrador ya fue aprobado o enviado; no se puede reemplazar.'),{status:409});
    const history=[...(Array.isArray(old.history)?old.history:[]),{version:old.version||1,status:old.status,mensaje_atleta:old.mensaje_atleta,semaforo:old.semaforo,resumen:old.resumen,replaced_at:now}].slice(-5);
    const data={...clean,status:'draft',version:(Number(old.version)||1)+1,history,origin:'assistant',created_at:old.created_at||previous.created_at,updated_at:now};
    await db('workout_templates',`id=eq.${encodeURIComponent(previous.id)}`,{method:'PATCH',body:{template_data:data,updated_at:now},prefer:'return=minimal'});
    return{created:false,draft:draftView({...previous,updated_at:now,template_data:data})};
  }
  const data={...clean,status:'draft',version:1,history:[],origin:'assistant',created_at:now,updated_at:now};
  const name=clean.kind==='session'?`Feedback sesión ${clean.date}`:`Feedback semana ${clean.week_start}`;
  const row={id:crypto.randomUUID(),coach_user_id:coachId,athlete_id:clean.athlete_id,name,category:DRAFT,sport:'Internal',stimulus:'assistant',template_data:data,created_at:now,updated_at:now};
  const rows=await db('workout_templates','',{method:'POST',body:row,prefer:'return=representation'});
  return{created:true,draft:draftView(rows[0]||row)};
}
async function createDraft(session,athleteId,body){await coachAthlete(session.coach_user_id,athleteId);const result=await saveDraft(session.coach_user_id,athleteId,body);await audit(session,result.created?'draft_created':'draft_replaced',{draft_id:result.draft.id,athlete_id:athleteId,kind:result.draft.kind,idempotency_key:result.draft.idempotency_key,version:result.draft.version});return result}
// Filters: status ("pending" = draft|ready|needs_review, "all", or one status), athlete_id, kind.
function filterDrafts(rows,filters={}){
  const status=safe(filters.status,20)||'pending',athleteId=safe(filters.athlete_id,80),kind=safe(filters.kind,20);
  if(status!=='pending'&&status!=='all'&&!DRAFT_STATUSES.includes(status))throw badRequest('Estado de borrador no válido.');
  const seen=new Set(),out=[];
  for(const draft of rows){
    const key=draft.idempotency_key||draft.id;if(seen.has(key))continue;seen.add(key);
    if(status==='pending'&&!DRAFT_PENDING.includes(draft.status))continue;
    if(status!=='pending'&&status!=='all'&&draft.status!==status)continue;
    if(athleteId&&draft.athlete_id!==athleteId)continue;
    if(kind&&draft.kind!==kind)continue;
    out.push(draft);
  }
  return out.slice(0,Math.max(1,Math.min(200,Number(filters.limit)||100)));
}
async function listDrafts(coachId,filters={},db=sb){const rows=await db('workout_templates',`coach_user_id=eq.${encodeURIComponent(coachId)}&category=eq.${encodeURIComponent(DRAFT)}&select=id,athlete_id,template_data,created_at,updated_at&order=updated_at.desc&limit=500`);return filterDrafts(rows.map(draftView),filters)}

// Lo que necesita el Analista (assistant-analyst.js) para leer datos.
const analystDeps={sb,listDrafts:(coachId,filters)=>listDrafts(coachId,filters),proposals:coachId=>proposals(coachId),detail:(coachId,athleteId,externalId)=>{const fn=globalThis.__runflowActivityDetail;if(!fn)throw Object.assign(new Error('RunFlow no puede leer el detalle de la actividad ahora mismo.'),{status:503});return fn(coachId,athleteId,externalId)}};

